import pyomo.environ as pyo

DATA = {
    "products": ["Meaties", "Yummies"],
    "price": {"Meaties": 2.80, "Yummies": 2.00},
    "cereal_lbs": {"Meaties": 2.0, "Yummies": 3.0},
    "meat_lbs": {"Meaties": 3.0, "Yummies": 1.5},
    "blend_cost": {"Meaties": 0.25, "Yummies": 0.20},
    "cereal_cost_per_lb": 0.20,
    "meat_cost_per_lb": 0.50,
    "cereal_available_lbs": 400000.0,
    "meat_available_lbs": 300000.0,
    "meaties_machine_capacity": 90000.0,
}


def build_model(data=None):
    d = data or DATA
    products = d["products"]

    model = pyo.ConcreteModel()
    model.P = pyo.Set(initialize=products)

    # Net margin per package = price - input cost - blend/pack cost
    def net_margin(p):
        return (
            d["price"][p]
            - d["cereal_lbs"][p] * d["cereal_cost_per_lb"]
            - d["meat_lbs"][p] * d["meat_cost_per_lb"]
            - d["blend_cost"][p]
        )

    # Decision: packages produced per product
    def prod_bounds(m, p):
        if p == "Meaties":
            return (0.0, d["meaties_machine_capacity"])
        return (0.0, None)

    model.production = pyo.Var(
        model.P, within=pyo.NonNegativeReals, bounds=prod_bounds
    )

    # Objective: maximize total profit
    model.obj = pyo.Objective(
        expr=sum(net_margin(p) * model.production[p] for p in model.P),
        sense=pyo.maximize,
    )

    # Cereal availability
    def cereal_rule(m):
        return sum(
            d["cereal_lbs"][p] * m.production[p] for p in m.P
        ) <= d["cereal_available_lbs"]

    model.cereal_limit = pyo.Constraint(rule=cereal_rule)

    # Meat availability
    def meat_rule(m):
        return sum(
            d["meat_lbs"][p] * m.production[p] for p in m.P
        ) <= d["meat_available_lbs"]

    model.meat_limit = pyo.Constraint(rule=meat_rule)

    # Machine capacity for Meaties
    def machine_rule(m):
        return m.production["Meaties"] <= d["meaties_machine_capacity"]

    model.machine_limit = pyo.Constraint(rule=machine_rule)

    return model


